import json, re
d = json.load(open('parecer.json'))
print('JSON OK; fundamentos =', len(d['fundamentos']))
# checagens numéricas do caso central
nums = json.dumps(d)
for k in ('665584','665.584','682152','682.152'):
    pass
e = d['exposicao'] if 'exposicao' in d else None
def find(o, path=''):
    if isinstance(o, dict):
        for k,v in o.items(): yield from find(v, f'{path}/{k}')
    elif isinstance(o, list):
        for i,v in enumerate(o): yield from find(v, f'{path}[{i}]')
    else:
        yield path, o
flat = dict(find(d))
for p,v in flat.items():
    if any(s in p.lower() for s in ('total','provis','exposi')) and isinstance(v,(int,float)):
        print(f'{p} = {v:,.2f}')
# markdown: títulos novos presentes e ordem correta
md = open('parecer.md').read()
print([h for h in re.findall(r'^#{2,3} .+', md, re.M) if '4.1' in h or '7.1' in h])
assert 'dice' not in md and md.count('### 4.1')==1 and md.count('### 7.1')==1
print('parecer.md OK —', len(md.splitlines()), 'linhas')
EOF

